/* @lc app=leetcode id=1348 lang=kotlin */
class TweetCounts(val map: MutableMap<String, java.util.TreeMap<Int, Int>> = mutableMapOf()) { fun recordTweet(tweetName: String, time: Int) = map.getOrPut(tweetName) { java.util.TreeMap() }.merge(time, 1, Int::sum).run { } fun getTweetCountsPerFrequency(freq: String, tweetName: String, startTime: Int, endTime: Int): List<Int> = (if (freq == "minute") 60 else if (freq == "hour") 3600 else 86400).let { f -> IntArray((endTime - startTime) / f + 1).also { res -> map[tweetName]?.subMap(startTime, true, endTime, true)?.forEach { (t, c) -> res[(t - startTime) / f] += c } }.toList() } }